<style>
:root{color-scheme:dark;--bg:#171f26;--surface:#1d2832;--line:#2b3843;--ink:#e5eaf0;--muted:#9baab9;--accent:#1599f6;--green:#35cc84}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}a{color:inherit;text-decoration:none}button,input,select,textarea{font:inherit}button,a,input,select,textarea{-webkit-tap-highlight-color:transparent}a:focus-visible,button:focus-visible,input:focus-visible{outline:2px solid var(--accent);outline-offset:4px}.workspace{max-width:1040px;margin:auto;padding-bottom:110px}.preview-note{background:#203d57;color:#a8d8ff;padding:9px 16px;text-align:center;font-size:12px}.workspace-header{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:18px 24px;border-top:3px solid var(--accent);border-bottom:1px solid var(--line)}.brand-pill,.balance-pill{display:flex;align-items:center;gap:10px;background:#1b252d;border:1px solid var(--line);border-radius:26px;padding:8px 12px;min-width:0}.brand-pill{max-width:65%}.brand-pill strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.brand-mark{display:grid;place-items:center;width:26px;height:26px;border-radius:8px;background:#158fe8;color:white;font-weight:800;flex:none}.balance-pill{white-space:nowrap}.plus{display:grid;place-items:center;border-radius:50%;background:#2fba67;color:#10281a;width:20px;height:20px;font-weight:800}main{padding:24px}.heading{margin-bottom:24px}.eyebrow{font-size:11px;font-weight:700;letter-spacing:.13em;color:var(--accent)}h1{font-size:28px;margin:6px 0}h2{font-size:18px;margin:0}h3{font-size:16px;margin:10px 0}p{color:var(--muted);margin:6px 0;overflow-wrap:anywhere}.summary-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:24px}.summary{background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:18px;min-width:0}.summary small{color:#bdc9d6;display:block;font-size:12px}.summary strong{display:block;font-size:24px;margin:6px 0;overflow-wrap:anywhere}.summary a{font-size:12px;color:#afdcff}.summary.blue{background:#173b59;border-color:#22567d}.summary.purple{background:#322d52;border-color:#49416f}.summary.green{background:#193d35;border-color:#28584a}.menu-list{border:1px solid var(--line);border-radius:14px;overflow:hidden;margin-bottom:24px;background:#1a252e}.menu-list>a{display:flex;align-items:center;gap:16px;padding:17px 20px;border-bottom:1px solid var(--line);font-weight:600}.menu-list>a:last-child{border:0}.menu-list>a:hover{background:#243542}.icon{display:inline-block;width:22px;height:22px;fill:currentColor;flex:none}.chevron{margin-left:auto;color:#7c8c99;width:16px}.content-card{border:1px solid var(--line);border-radius:14px;background:var(--surface);padding:20px}.section-heading{display:flex;align-items:center;justify-content:space-between;gap:12px}.section-heading>a,.back{color:var(--accent);font-size:13px}.empty{text-align:center;padding:32px 12px}.empty>.icon{width:32px;height:32px;color:var(--accent)}.primary{display:inline-flex;align-items:center;justify-content:center;background:#168fe5;border:1px solid #249ff5;color:white;border-radius:9px;padding:10px 18px;font-weight:600;margin-top:16px}.primary:disabled{opacity:.55;cursor:not-allowed}.order-row{display:flex;justify-content:space-between;gap:16px;padding:16px 0;border-bottom:1px solid var(--line)}.order-row>div{min-width:0}.order-row strong{display:block;overflow-wrap:anywhere}.order-row small{color:var(--muted)}.status{align-self:center;background:#503d22;color:#ffcf7e;padding:4px 10px;border-radius:20px;font-size:12px}.status.success{background:#1d4938;color:#7fe6b1}.announcement{padding:16px;background:#213d58;border:1px solid #315778;border-radius:12px;white-space:pre-wrap;margin-bottom:20px}.workspace-bottom{position:fixed;bottom:0;left:0;right:0;background:linear-gradient(transparent,var(--bg) 25%);padding:18px 16px max(14px,env(safe-area-inset-bottom));z-index:10}.workspace-bottom nav{max-width:600px;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));margin:auto;background:#1b252e;border:1px solid #35424d;border-radius:32px;padding:4px}.workspace-bottom a{display:flex;flex-direction:column;align-items:center;gap:2px;padding:6px 8px;color:#b5c0ca;font-size:11px;border-radius:26px}.workspace-bottom a[aria-current]{background:#253748;color:#20a5ff}.workspace-bottom .icon{width:21px;height:21px}label{display:block;margin-top:16px;color:#bcc9d6}input,select,textarea{display:block;width:100%;padding:12px;margin-top:6px;border:1px solid #3a4b59;background:#14212b;color:var(--ink);border-radius:8px;resize:vertical}@media(max-width:650px){main{padding:18px 16px}.workspace-header{padding:12px 16px}.summary-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.summary{padding:14px}.summary strong{font-size:21px}h1{font-size:24px}}@media(max-width:360px){.brand-pill{max-width:56%;font-size:13px}.balance-pill{font-size:12px}.workspace-header{gap:6px;padding-inline:10px}.summary strong{font-size:18px}}
</style>
